	if (!spreadsheetId) throw new Error("Spreadsheet ID খালি রয়েছে।");
	const htmlRes = await fetchPublicGoogleUrl(`https://docs.google.com/spreadsheets/d/${encodeURIComponent(spreadsheetId)}/htmlview`);
	if (htmlRes.privateSheet) throw new PublicSheetAccessError();
	if (!htmlRes.ok || !htmlRes.text) throw new Error(`Google Sheet পাওয়া যায়নি (HTTP ${htmlRes.status})। লিংক/ID সঠিক কিনা ও Share অপশন চালু আছে কিনা দেখুন।`);
