	const gidMap = {};
	const pushTab = (name, gid) => {
		const cleanName = name.trim();
		if (!cleanName || !gid) return;
		if (!gidMap[cleanName]) {
			sheetTitles.push(cleanName);
			gidMap[cleanName] = gid;
			const numGid = Number(gid);
			if (Number.isFinite(numGid)) sheetIdMap[cleanName] = numGid;
		}
	};
	const jsRegex = /items\.push\(\{name:\s*"((?:[^"\\]|\\.)*)"[^}]*?gid(?:=|\\x3d|\\u003d)(\d+)/gi;
	let m;
	while ((m = jsRegex.exec(html)) !== null) pushTab(decodeJsQuotedString(m[1]), m[2]);
