async function fetchExternalChallansFromSheet(rawSpreadsheetId, accessToken) {
	const spreadsheetId = extractSpreadsheetId(rawSpreadsheetId);
	if (!spreadsheetId) throw new Error("চালান Google Sheet ID বা লিংক দিন।");
	if (accessToken) {
		const meta = await getSpreadsheetMetadata(accessToken, spreadsheetId);
		const primaryMatch = findMatchingSheetTitle(meta.sheetTitles, ALLOC_SHEET_TABS.challans.name, ALLOC_SHEET_TABS.challans.aliases);
		const candidates = primaryMatch ? [primaryMatch, ...meta.sheetTitles.filter((t) => t !== primaryMatch)] : meta.sheetTitles;
		for (const tab of candidates.slice(0, 6)) {
			const escaped = tab.replace(/'/g, "''");
			const parsed = parseChallanRowsFromTable((await googleFetch(`${SHEETS_API_BASE}/${encodeURIComponent(spreadsheetId)}/values:batchGet?ranges=${encodeURIComponent(`'${escaped}'!A1:Z`)}&majorDimension=ROWS&valueRenderOption=UNFORMATTED_VALUE`, accessToken)).valueRanges?.[0]?.values || []);
			if (parsed.length > 0) return {
				challans: parsed,
				title: meta.title,
				tabUsed: tab
			};
		}
		return {
			challans: [],
			title: meta.title
		};
	}
	const { meta, gidMap } = await getPublicSpreadsheetMetadata(spreadsheetId);
	const primaryMatch = findMatchingSheetTitle(meta.sheetTitles, ALLOC_SHEET_TABS.challans.name, ALLOC_SHEET_TABS.challans.aliases);
	const candidates = meta.sheetTitles.length > 0 ? primaryMatch ? [primaryMatch, ...meta.sheetTitles.filter((t) => t !== primaryMatch)] : meta.sheetTitles : [
		ALLOC_SHEET_TABS.challans.name,
		"Challan",
		"Sheet1",
		"Form Responses 1"
	];
	for (const tab of candidates.slice(0, 6)) {
		const parsed = parseChallanRowsFromTable(await fetchPublicCsvSheet(spreadsheetId, gidMap[tab], tab));
		if (parsed.length > 0) return {
			challans: parsed,
			title: meta.title,
			tabUsed: tab
		};
	}
	return {
		challans: [],
		title: meta.title
	};
}
async function fetchExternalChallansFromAppsScript(rawUrl) {
	const url = rawUrl.trim();
	if (!url) throw new Error("চালান ওয়েব অ্যাপ URL দিন।");
	const isNativeOrLocal = typeof window !== "undefined" && window.location.protocol === "file:";
	let json = null;
	if (!isNativeOrLocal) {
		const body = await (await fetch("/api/gas-proxy", {
			method: "POST",
			headers: { "Content-Type": "application/json" },
			body: JSON.stringify({
				url,
				action: "getAppData"
			})
		})).json();
		if (!body?.ok) throw new Error(body?.error || "চালান Apps Script থেকে ডেটা পাওয়া যায়নি।");
		json = body.data;
	} else {
		const u = new URL(url);
		u.searchParams.set("api", "1");
		u.searchParams.set("action", "getAppData");
		json = await (await fetch(u.toString())).json();
	}
	const root = json && typeof json === "object" ? json : {};
	const rawList = Array.isArray(json) ? json : Array.isArray(root.challans) ? root.challans : Array.isArray(root.data) ? root.data : Array.isArray(root.rows) ? root.rows : [];
	if (rawList.length === 0) return {
		challans: [],
		sourceUrl: url
	};
	let table;
	if (Array.isArray(rawList[0])) table = rawList;
	else {
		const firstObj = rawList[0];
		const headers = Object.keys(firstObj);
		table = [headers, ...rawList.map((item) => {
			const obj = item || {};
			return headers.map((h) => obj[h] ?? "");
		})];
	}
	return {
		challans: parseChallanRowsFromTable(table),
		sourceUrl: url
	};
}
async function fetchAllocationFromOAuthSheet(accessToken, rawSpreadsheetId, currentDb) {
	const spreadsheetId = extractSpreadsheetId(rawSpreadsheetId);
	if (!spreadsheetId) throw new Error("Google Sheet ID বা লিংক দিন।");
	const meta = await getSpreadsheetMetadata(accessToken, spreadsheetId);
	const entries = Object.entries(ALLOC_SHEET_TABS);
	const matchedMap = /* @__PURE__ */ new Map();
	const matchedTabs = /* @__PURE__ */ new Set();
	const matchedTabNames = [];
	const ranges = [];
	for (const [key, def] of entries) {
		const matched = findMatchingSheetTitle(meta.sheetTitles, def.name, def.aliases);
		if (matched) {
			matchedMap.set(key, matched);
			matchedTabs.add(key);
			matchedTabNames.push(matched);
			const escaped = matched.replace(/'/g, "''");
			ranges.push(`'${escaped}'!A1:Z`);
		}
	}
	if (matchedTabs.size === 0 && meta.sheetTitles.length > 0) throw new Error(`"${meta.title}" শিটে বরাদ্দ/ডিও-এর কাঙ্ক্ষিত ট্যাব পাওয়া যায়নি (পাওয়া ট্যাব: ${meta.sheetTitles.slice(0, 6).join(", ")}).`);
	const rawTables = {};
	if (ranges.length > 0) {
		const params = new URLSearchParams();
		ranges.forEach((r) => params.append("ranges", r));
		params.set("majorDimension", "ROWS");
		params.set("valueRenderOption", "UNFORMATTED_VALUE");
		const resp = await googleFetch(`${SHEETS_API_BASE}/${encodeURIComponent(spreadsheetId)}/values:batchGet?${params.toString()}`, accessToken);
		const matchedKeys = Array.from(matchedMap.keys());
		(resp.valueRanges || []).forEach((vr, idx) => {
			const k = matchedKeys[idx];
			if (k) rawTables[k] = vr.values || [];
		});
	}
	return {
		db: buildAllocationDbFromRawTables(rawTables, matchedTabs, currentDb),
		title: meta.title,
		tabsFound: meta.sheetTitles,
		matchedTabNames
	};
}
async function autoDetectAllocationSpreadsheets(accessToken) {
	const files = await listUserSpreadsheets(accessToken);
	let main;
	let challan;
	const sample = files.slice(0, 15);
	for (let i = 0; i < sample.length; i += 5) {
		const chunk = sample.slice(i, i + 5);
		const metas = await Promise.all(chunk.map(async (file) => {
			try {
				return {
					file,
					meta: await getSpreadsheetMetadata(accessToken, file.id)
				};
			} catch {
				return null;
			}
		}));
		for (const item of metas) {
			if (!item) continue;
			const titles = item.meta.sheetTitles;
			const hasMin = Boolean(findMatchingSheetTitle(titles, ALLOC_SHEET_TABS.ministry.name, ALLOC_SHEET_TABS.ministry.aliases));
			const hasSub = Boolean(findMatchingSheetTitle(titles, ALLOC_SHEET_TABS.dealerSub.name, ALLOC_SHEET_TABS.dealerSub.aliases));
			const hasDo = Boolean(findMatchingSheetTitle(titles, ALLOC_SHEET_TABS.doIssue.name, ALLOC_SHEET_TABS.doIssue.aliases));
			const hasChallan = Boolean(findMatchingSheetTitle(titles, ALLOC_SHEET_TABS.challans.name, ALLOC_SHEET_TABS.challans.aliases));
			const looksChallanOnly = hasChallan && !hasMin && !hasSub && !hasDo;
			if (!main && (hasMin || hasSub || hasDo)) main = item;
			if (!challan && (looksChallanOnly || hasChallan && item.file.id !== main?.file.id)) challan = item;
		}
		if (main && challan) break;
	}
	return {
		files,
		main,
		challan
	};
}
